import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String buffer = scanner.next();
        int length = buffer.length();
        StringBuilder result = new StringBuilder();
        boolean at_found = false;

        // Check if '@' is present
        for (int i = 0; i < length; i++) {
            if (buffer.charAt(i) == '@') {
                at_found = true;
                break;
            }
        }

        char[] bufChars = buffer.toCharArray();

        for (int i = 0; i < length; i++) {
            if (i + 2 < length && bufChars[i] == 'd' && bufChars[i + 1] == 'o' && bufChars[i + 2] == 't' && i != 0 && i != length - 3) {
                result.append('.');
                bufChars[i] = ' ';
                bufChars[i + 1] = ' ';
                bufChars[i + 2] = ' ';
            } else if (i + 1 < length && bufChars[i] == 'a' && bufChars[i + 1] == 't' && i != 0 && i != length - 2 && !at_found) {
                result.append('@');
                bufChars[i] = ' ';
                bufChars[i + 1] = ' ';
                at_found = true;
            } else if (bufChars[i] != ' ') {
                result.append(bufChars[i]);
            }
        }

        System.out.println(result.toString());
        scanner.close();
    }
}
